-- A deterministic owner-only test clock. No public API accepts a browser-supplied time.
create function public.customer_test_now() returns timestamptz language sql stable as $$select date_trunc('day',clock_timestamp())+interval '10 hours'$$;
update private.customer_journeys set entered_at=public.customer_test_now()-interval '8 days',setup_started_at=public.customer_test_now()-interval '4 days',last_seen_at=public.customer_test_now()-interval '2 hours' where user_id='00000000-0000-4000-8000-000000000002';
select public.assert_customer(private.collect_customer_journeys(date_trunc('day',public.customer_test_now())+interval '21 hours')=0,'quiet hours suppress in-app optional collection');
select public.assert_customer(private.collect_customer_journeys(public.customer_test_now())=1,'one latest due consented reminder is emitted');
select public.assert_customer((select count(*)=1 from private.customer_journey_events where user_id='00000000-0000-4000-8000-000000000002' and kind='customer_setup_72h'),'72h slot wins when both setup slots were missed');
select public.assert_customer(private.collect_customer_journeys(public.customer_test_now())=0,'same-time collector replay emits nothing');
select public.assert_customer(private.collect_customer_journeys(public.customer_test_now()+interval '2 days')=0,'one optional per seven days across categories');
select public.assert_customer(private.collect_customer_journeys(public.customer_test_now()+interval '8 days')=1,'a later first-booking nudge may be earned after seven days');
-- A third otherwise-eligible reminder in a different setup revision must still respect the cap.
update private.customer_journeys set setup_started_at=public.customer_test_now()+interval '12 days',setup_revision=1 where user_id='00000000-0000-4000-8000-000000000002';
select public.assert_customer(private.collect_customer_journeys(public.customer_test_now()+interval '16 days')=0,'at most two optional updates per thirty days');
